import unittest

from geo import distance_km, midpoint


class TestGeo(unittest.TestCase):
    def test_a_point_is_no_distance_from_itself(self):
        self.assertEqual(distance_km((51.5, -0.1), (51.5, -0.1)), 0)

    def test_the_midpoint_of_two_points(self):
        self.assertEqual(midpoint((0, 0), (2, 4)), (1, 2))

